import React, { useState, useEffect, useRef } from 'react';
import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs'; // <--- NEW IMPORT
import './ChatComponent.css';

const ChatComponent = ({ currentUserId, receiverId }) => {
    const [messages, setMessages] = useState([]);
    const [newMessage, setNewMessage] = useState("");
    const stompClientRef = useRef(null);
    const messagesEndRef = useRef(null);

    // Auto-scroll to bottom
    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        scrollToBottom();
    }, [messages]);

    useEffect(() => {
        // 1. Initialize the Client
        const client = new Client({
            // We use webSocketFactory to wrap SockJS
            webSocketFactory: () => new SockJS('http://localhost:8080/ws'),
            // Reconnect automatically if connection is lost
            reconnectDelay: 5000,
            // Clean up console logs
            debug: () => {},
            onConnect: () => {
                // 2. Subscribe to your topic
                client.subscribe(`/topic/messages/${currentUserId}`, (message) => {
                    const receivedMsg = JSON.parse(message.body);
                    if (receivedMsg.senderId === receiverId) {
                        setMessages((prev) => [...prev, receivedMsg]);
                    }
                });
            },
        });

        // Start connection
        client.activate();
        stompClientRef.current = client;

        return () => {
            // Cleanup on unmount
            client.deactivate();
        };
    }, [currentUserId, receiverId]);

    const sendMessage = (e) => {
        e.preventDefault();
        if (newMessage.trim() && stompClientRef.current && stompClientRef.current.connected) {
            const chatMessage = {
                senderId: currentUserId,
                receiverId: receiverId,
                content: newMessage,
                timestamp: Date.now(),
                isRead: false
            };

            // 3. Send Message
            stompClientRef.current.publish({
                destination: "/app/chat",
                body: JSON.stringify(chatMessage),
            });

            // Optimistic UI Update
            setMessages((prev) => [...prev, chatMessage]);
            setNewMessage("");
        }
    };

    return (
        <div className="chat-container">
            <div className="chat-box">
                {messages.length === 0 && (
                    <p style={{textAlign: 'center', color: '#888', fontSize: '0.8rem'}}>
                        Start chatting...
                    </p>
                )}

                {messages.map((msg, index) => (
                    <div
                        key={index}
                        className={`message-bubble ${msg.senderId === currentUserId ? 'sent' : 'received'}`}
                    >
                        {msg.content}
                    </div>
                ))}
                <div ref={messagesEndRef} />
            </div>

            <form className="chat-input-area" onSubmit={sendMessage}>
                <input
                    type="text"
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    placeholder="Type..."
                />
                <button type="submit">➤</button>
            </form>
        </div>
    );
};

export default ChatComponent;
